    allergenes: ["fruits_a_coque", "gluten", "lait", "oeuf"],
    tags: ["tarte", "amande"],
    parfum_principal: "amande",
    note_concepteur: "1 x 4 PERS 2 x 6 PERS 1 x 8 PERS 7 PORTIONS 4 tartes Composition : 	Pâte sucrée Appareil passion ou framboise Glaçage gelé Meringue italienne Décor fruits frais Recette gelée MONTAGE Faire précuire les fonds de pâte sucrée a blanc sur tourtière (couleur très clair) Garnir avec l’appareil Cuire à 180°c, dès que l’appareil est figé sortir du four Laisser refroidir Décorer meringue, puis flamber f (grosses larmes sur le côté, laisser le centre vide pour couler la gelée de fruit) Douille n° 12 pour la meringue Laisser figer puis décorer de quelques fruits frais Tarte chocolat lactée, crème caramel fleur de sel pour 7-8 pers Réaliser la pâte sablée aux amandes ou noisettes 300 g de beurre 190 g de sucre glace silice 60 g de poudre de noisettes 4 g de sel 100 g d’œufs 500 g de farine - Mélanger le beurre pommade avec le sucre, le sel, la poudre de noisettes ou amandes et les œufs. - Ajouter en dernier la farine. (Ne pas trop travailler la pâte pour éviter de lui donner du corps). - Mettre au froid 12 heures environ. - Étaler la pâte dans un cercle foncer et piquer (on peut ajouter des noyaux dans la tarte pour une meilleure cuisson à blanc.) - Enfourner 20 minutes à 160°C-180°C environ Réaliser la crème caramel beurre salé : - Dans une casserole, porter à ébullition 400g de sucre en semoule 30g d’eau, Jusqu’à obtention d’un joli caramel doré. - Ajouter ensuite 160 g de crème liquide UHT à 35% de mg légèrement tiédie (attention aux éclaboussures !) 2 g de fleur de sel Et enfin 150 g de beurre fin coupé en morceaux. - Verser la crème caramel beurre salé sur le fond de tarte préalablement cuite et mettre au frais. Réaliser la ganache chocolat au lait : - Dans une casserole, faire chauffer 800 gr de crème liquide + 60 Gr de beurre fin Et verser sur 1000 g de chocolat au lait (lactée Élysée de chez cacao Barry) - Laisser fondre doucement en mélangeant (émulsionner à l’aide d’un mixer) pour obtenir une belle ganache lisse. - Verser délicatement la ganache sur la tarte (la crème caramel a dû durcir un peu). - Mettre au frais plusieurs heures (une nuit c’est encore mieux !). - Décorer et déguster. Nota : On peut la servir à l’assiette avec une belle boule de glace vanille. - Ou bien, servir avec un bon café… PATE SABLÉE AMANDES DACQUOISE COCO CRÈME CITRON 3 tartes PATE SABLÉE prévoir 4 ananas CRÈME NOIX DE COCO AMANDES CARAMÉLISÉES 250 g d'amandes bâtonnets 50 g de sirop à 30°B Mélanger les amandes et le sirop à 30°B. -Chauffer à 35 degrés environ -Mixer 1 minute -Utiliser à 28/30 degrés pour le blanc -Utiliser à 32/33 degrés pour le lait -Utiliser à 34/35 degrés pour le noir Tout dépend de la texture de votre glaçage Montage et finitions : Cuire les fonds de sablé breton à 180°C pendant environ 30mn au four à sole. Refroidir puis isoler les fonds de tartes avec du beurre de cacao fondu. Glacer les crémeux chocolat avec le glaçage noir, puis les déposer sur les fonds de sablé breton, décorer avec des amandes bâtonnets caramélisées et ronds de chocolat noir et lait de différentes tailles. Pour 3 tartes de 20 cm de diamètre ou une vingtaine de tartelettes de 7 cm de diamètre Pâte sablée aux amandes 300 g de beurre 5 g de sel 185 g de sucre glace 60 g de poudre d’amandes brute 105 g d’œufs 500 g de farine T55 -Chauffer à 35 degrés environ -Mixer 1 minute -Utiliser à 28/30 degrés pour le blanc -Utiliser à 32/33 degrés pour le lait -Utiliser à 34/35 degrés pour le noir Tout dépend de la texture de votre glaçage",
